def structure(x):
    if isinstance(x,dict): return {k:structure(v) for k,v in x.items()}
    if isinstance(x,(np.ndarray,torch.Tensor)): return (tuple(x.shape),str(x.dtype))
    if isinstance(x,(list,tuple)): return [structure(v) for v in x[:3]]
    return str(x)[:100]
